    44	// ParseAcceptedLimits reads the `### Accepted limits` section of a spec body.
    45	// It returns the limits and the problems that keep the section from being
    46	// read as written: a bullet that is not `- L<N>: ...`, a repeated id, or a
    47	// limit that does not say why it is accepted ("Accepted because ..." or
    48	// "Aceito porque ...").
    49	func ParseAcceptedLimits(body string) ([]ReviewAcceptedLimit, []string) {
    50		var limits []ReviewAcceptedLimit
    51		var problems []string
    52		in := false
    53		seen := map[string]bool{}
    54		for _, line := range strings.Split(body, "\n") {
    55			trimmed := strings.TrimSpace(line)
    56			if strings.HasPrefix(trimmed, "#") {
    57				in = strings.EqualFold(strings.TrimSpace(strings.TrimLeft(trimmed, "#")), "Accepted limits") || strings.EqualFold(strings.TrimSpace(strings.TrimLeft(trimmed, "#")), "Limites aceitos")
    58				continue
    59			}
    60			if !in || !strings.HasPrefix(trimmed, "- ") {
    61				continue
    62			}
    63			m := acceptedLimitRE.FindStringSubmatch(trimmed)
    64			if m == nil {
    65				problems = append(problems, "accepted limit "+quoteLedgerText(trimmed)+" is not written as '- L<N>: <assumption>. Accepted because <reason>.'")
    66				continue
    67			}
    68			if seen[m[1]] {
    69				problems = append(problems, "accepted limit "+m[1]+" is declared twice")
    70				continue
    71			}
    72			seen[m[1]] = true
    73			if !hasAcceptedLimitReason(m[2]) {
    74				problems = append(problems, "accepted limit "+m[1]+" does not say why it is accepted ('Accepted because ...')")
    75			}
    76			limits = append(limits, ReviewAcceptedLimit{ID: m[1], Text: strings.TrimSpace(m[2])})
    77		}
    78		return limits, problems
    79	}
